      i--;
    } else {
      j--;
    }
  }
  return out.reverse().join("");
}

const pairs = [["AGCAT", "GAC"], ["GATTACA", "GCATGCT"], ["AAAA", "TTTT"]];
for (const [a, b] of pairs) {
  const shared = rebuild(a, b, lcsTable(a, b));
  console.log(`${a} and ${b}: ${shared === "" ? "none" : shared}`);
}

